/// <summary>
/// This is a service class which process the business logic for the vendor change request.
/// </summary>
class METVendorChangeRequestService
{
    Set vendorChangerequestsProcessed;
    
    //Task110346_CB409-D365ToPIM-Supplier change request- start
    private List        vendAccountNumberList;              //C - Task 259910: CB409 - PE-128: D365 to PIM
    private List        coverageWareHouseIdList;
    private List        coverageWhsIdVendAccountNumberList; //C - Task 259910: CB409 - PE-128: D365 to PIM
    private ItemId      itemNumber;
    private VendAccount vendAccountNumber;
    //Task110346_CB409-D365ToPIM-Supplier change request- end
    boolean             calledFromPackChange;

    InventParameters inventParameters = InventParameters::find();

    MetChangeReqEffectiveDate currentDate;


}

Method.Source:
    /// <summary>
    /// This process method initiates the business flow orchestration for vendor change requests.
    /// </summary>
    /// <param name = "_data">Contract parameters.</param>
    public void processOperation(METVendorChangeRequestContract _data)
    {
        #OCCRetryCount
        System.Exception netExcepn;

        try
        {
            METVendorChangeRequest metVendorChangeRequest;
            InventSiteId inventSiteId;
            inventSiteId = _data.parmInventSiteId();
            vendorChangerequestsProcessed = new Set(Types::Int64);
            currentDate = DateTimeUtil::date(DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::utcNow(), DateTimeUtil::getUserPreferredTimeZone()));
            //Task110346_CB409-D365ToPIM-Supplier change request- start
            boolean validateVendorChangeRequests = true;
            //Task110346_CB409-D365ToPIM-Supplier change request- end
            calledFromPackChange = _data.parmCalledFromDefaultForm();

            ttsbegin;
            while select metVendorChangeRequest
                where metVendorChangeRequest.Status != METVendChangeReqStatus::Completed
                && metVendorChangeRequest.ChangeReqEffectiveDate <= currentDate
            {
                //Bug 303894- start
                vendAccountNumberList                   = new List(Types::String);
                coverageWareHouseIdList                 = new List(Types::String);
                coverageWhsIdVendAccountNumberList      = new List(Types::String);
                //Bug 303894- end

                //Bug 351481 - start
                vendAccountNumber = '';
                //Bug 351481 - end

                if(!inventSiteId ||
                    (inventSiteId && (metVendorChangeRequest.SiteId == inventSiteId)) ||
                    (calledFromPackChange && inventSiteId && _data.parmItemId() && (metVendorChangeRequest.SiteId == inventSiteId) && (metVendorChangeRequest.ItemId == _data.parmItemId())))
                {
                    validateVendorChangeRequests = this.validateVendorChangeRequests(metVendorChangeRequest);
                }

                //Task110346_CB409-D365ToPIM-Supplier change request- start
                if (validateVendorChangeRequests && !coverageWareHouseIdList.empty() && !vendAccountNumberList.empty())
                {
                    //NS - Task 259910: CB409 - PE-128: D365 to PIM
                    ListIterator coverageWhsIdItr       = new ListIterator(coverageWareHouseIdList);
                    
                    while (coverageWhsIdItr.more())
                    {
                        //Bug 303894- start
                        this.addVendorCombinationsForWarehouse( coverageWhsIdItr.value(), vendAccountNumberList);

                        coverageWhsIdItr.next();
                        //Bug 303894- end
                    }
                    //NE - Task 259910: CB409 - PE-128: D365 to PIM
                    
                    this.triggerSupplierChangeCompleteBusinessEvent(itemNumber, coverageWhsIdVendAccountNumberList);
                    this.runBasePriceVersionJob(metVendorChangeRequest);
                    coverageWareHouseIdList = new List(Types::String);
                }
                //Task110346_CB409-D365ToPIM-Supplier change request- end
            }
            ttscommit;
        }
        catch (Exception::CLRError)
        {
            netExcepn = CLRInterop::getLastException();
            throw error(netExcepn.ToString());
        }
        catch (Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch
        {
            exceptionTextFallThrough();
        }
    }

    /// <summary>
    /// All validations related to the vendor change requests perform here.
    /// </summary>
    /// <param name = "_metVendorChangeRequest">Vendor change request record.</param>
    /// <returns>The error log is updated and the status is changed to error if any validation fails.</returns>
    private boolean validateVendorChangeRequests(METVendorChangeRequest _metVendorChangeRequest)
    {
        boolean ret = true;

        _metVendorChangeRequest.ChangeRequestLog = '';

        ReqItemTable reqItemTable;
        InventDim inventDim;

        METVendorChangeRequest parentChangeRequest = this.getParentvendorChangeRequest(_metVendorChangeRequest);

        if (parentChangeRequest.RecId)
        {
            return false;
        }

        select firstonly reqItemTable
        exists join inventDim
            where inventDim.inventDimId == reqItemTable.CovInventDimId
            && reqItemTable.ItemId == _metVendorChangeRequest.ItemId
            && inventDim.InventLocationId == _metVendorChangeRequest.InventLocationId
            && inventDim.InventSiteId == _metVendorChangeRequest.SiteId;

        if (reqItemTable.RecId && reqItemTable.ReqPOType == ReqPOType::Purch && reqItemTable.METInterCompanySourced == NoYes::No)
        {
            this.updateItemSubrangeAndPOTORecords(reqItemTable, _metVendorChangeRequest);
        }
        else if (reqItemTable.RecId && reqItemTable.ReqPOType == ReqPOType::Purch && reqItemTable.METInterCompanySourced == NoYes::Yes)
        {
            //CB886_IntercompanyFulfilmentProcess
            ReqItemTable    reqItemTableInterComp;
            InventDim       invDimInterComp;

            select firstOnly reqItemTableInterComp
                where reqItemTableInterComp.ItemId == _metVendorChangeRequest.ItemId
                join RecId from invDimInterComp
                where invDimInterComp.InventDimId == reqItemTableInterComp.CovInventDimId
                && invDimInterComp.InventSiteId == _metVendorChangeRequest.SiteId
                && invDimInterComp.InventLocationId == _metVendorChangeRequest.InventLocationId
                && reqItemTableInterComp.ReqPOType == ReqPOType::Purch
                && reqItemTableInterComp.METInterCompanySourced == NoYes::Yes;

            if (reqItemTableInterComp.RecId)
            {
                ret = this.validateInterCompanyVendorChangeRequest(inventParameters.METInterCompanyPurchaseLegalEntity, _metVendorChangeRequest.ItemId, _metVendorChangeRequest.SiteId, reqItemTableInterComp.METIntercompanySourcedWarehouse);
                if (ret)
                {
                    this.updateChangeReqForParentChildItemInterCompPO(_metVendorChangeRequest);
                    this.processItemSubRange(_metVendorChangeRequest, reqItemTableInterComp);
                    return ret;
                }
                else
                {
                    _metVendorChangeRequest.selectForUpdate(true);
                    _metVendorChangeRequest.Status = METVendChangeReqStatus::Error;
                    _metVendorChangeRequest.ChangeRequestLog += strFmt("@MET:PendingVCRInIntComp", inventParameters.METInterCompanyPurchaseLegalEntity, _metVendorChangeRequest.ItemId, reqItemTableInterComp.METIntercompanySourcedWarehouse);
                    _metVendorChangeRequest.update();
                    vendorChangerequestsProcessed.add(_metVendorChangeRequest.RecId);
                    ret = false;
                }
            }

            if (!reqItemTableInterComp.RecId && !vendorChangerequestsProcessed.in(_metVendorChangeRequest.RecId))
            {
                _metVendorChangeRequest.selectForUpdate(true);
                _metVendorChangeRequest.Status = METVendChangeReqStatus::Error;
                _metVendorChangeRequest.ChangeRequestLog += "@MET:NoItemCoverageError";
                _metVendorChangeRequest.update();
                vendorChangerequestsProcessed.add(_metVendorChangeRequest.RecId);
                ret = false;
            }
        }
        else if (reqItemTable.ReqPOType == ReqPOType::Transfer)
        {
            ReqItemTable reqTransfer;
            InventDim invDimTransfer;
            InventDim invDimPurch;
            ReqItemTable reqPurch;
            METReqItemTable metReqPurch;

            select firstOnly reqTransfer
            join RecId from invDimTransfer
                where invDimTransfer.InventDimId == reqTransfer.CovInventDimId
            join InventLocationId, InventSiteId from invDimPurch
                where invDimPurch.InventLocationId == reqTransfer.InventLocationIdReqMain
            join RecId from reqPurch
                where reqPurch.CovInventDimId == invDimPurch.InventDimId
            join PendingVendAccountNumber from metReqPurch
                where reqPurch.RecId == metReqPurch.RefRecId
                && reqTransfer.ItemId == _metVendorChangeRequest.ItemId
                && invDimTransfer.InventSiteId == _metVendorChangeRequest.SiteId
                && invDimTransfer.InventLocationId == _metVendorChangeRequest.InventLocationId
                && reqTransfer.ReqPOType == ReqPOType::Transfer
                && reqPurch.ReqPOType == ReqPOType::Purch;

            if (!reqPurch.RecId && !vendorChangerequestsProcessed.in(_metVendorChangeRequest.RecId))
            {
                _metVendorChangeRequest.selectForUpdate(true);
                _metVendorChangeRequest.Status = METVendChangeReqStatus::Error;
                _metVendorChangeRequest.ChangeRequestLog += "@MET:NoItemCoverageError";
                _metVendorChangeRequest.update();
                vendorChangerequestsProcessed.add(_metVendorChangeRequest.RecId);
                ret = false;
            }
            else
            {
                MetVendorChangeRequest metVendorChangeRequestPO;

                select firstonly metVendorChangeRequestPO
                    where metVendorChangeRequestPO.Status != METVendChangeReqStatus::Completed
                        && metVendorChangeRequestPO.ChangeReqEffectiveDate == _metVendorChangeRequest.ChangeReqEffectiveDate
                        && metVendorChangeRequestPO.InventLocationId == invDimPurch.InventLocationId
                        && metVendorChangeRequestPO.SiteId == invDimPurch.InventSiteId
                        && metVendorChangeRequestPO.ItemId == _metVendorChangeRequest.ItemId;

                if (!metVendorChangeRequestPO.RecId && metReqPurch.PendingVendAccountNumber == '' && !vendorChangerequestsProcessed.in(_metVendorChangeRequest.RecId))
                {
                    this.updateItemSubrangeAndPOTORecords(reqTransfer, _metVendorChangeRequest);
                }
                else if (metVendorChangeRequestPO.RecId)
                {
                    this.validateVendorChangeRequests(metVendorChangeRequestPO);
                }
                else if (this.validateVendorChangeRequest(_metVendorChangeRequest, reqTransfer))
                {
                    this.processNoErrorRecords(_metVendorChangeRequest, reqTransfer);
                    this.updateVendorChangeRequestStatus(_metVendorChangeRequest);
                }
            }
        }
        else if (!reqItemTable.RecId && !vendorChangerequestsProcessed.in(_metVendorChangeRequest.RecId))
        {
            _metVendorChangeRequest.selectForUpdate(true);
            _metVendorChangeRequest.Status = METVendChangeReqStatus::Error;
            _metVendorChangeRequest.ChangeRequestLog += "@MET:NoItemCoverageError";
            _metVendorChangeRequest.update();
            vendorChangerequestsProcessed.add(_metVendorChangeRequest.RecId);
            ret = false;
        }
     
        this.updateWaitingStatusForRecords(_metVendorChangeRequest);

        return ret;
    }

    /// <summary>
    /// Validate the vendor change request data
    /// </summary>
    /// <param name = "_legalEntity">Legal entity</param>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_siteId">Site</param>
    /// <param name = "_locationId">Warehouse</param>
    /// <returns>If retuen true means record exist; otherwise false</returns>
    public boolean validateInterCompanyVendorChangeRequest(DataAreaId _legalEntity,
                                                        ItemId _itemId,
                                                        InventSiteId _siteId,
                                                        InventLocationId _locationId)
    {
        boolean ret = true;

        changecompany(_legalEntity)
        {
            MetVendorChangeRequest metVendorChangeRequestPO = MetVendorChangeRequest::find(_itemId, _locationId, currentDate);

            if (metVendorChangeRequestPO && metVendorChangeRequestPO.Status != METVendChangeReqStatus::Completed)
            {
                ret = false;
            }
        }
        return ret;
    }

    /// <summary>
    /// Process the item subrange basis
    /// </summary>
    /// <param name = "_metVendorChangeRequest">MetVendorChangeRequest</param>
    /// <param name = "_reqItemTable">ReqItemTable</param>
    public void processItemSubRange(MetVendorChangeRequest _metVendorChangeRequest, ReqItemTable _reqItemTable)
    {
        METSubrangeId   subRangeValue;
         
        //Check the subrange value
        subRangeValue = this.getSubRangeValue(_metVendorChangeRequest.ItemId, _metVendorChangeRequest.SiteId);

        if (subRangeValue)
        {
            this.processVendChangeReqInterCompData(_metVendorChangeRequest, _reqItemTable); //Current item
            this.processItemSubRangeChilds(_metVendorChangeRequest, subRangeValue); //Current item subrange
        }
        else
        {
            this.processVendChangeReqInterCompData(_metVendorChangeRequest, _reqItemTable);
        }
    }

    /// <summary>
    /// All the same subrange items will be processed for vendor change request.
    /// </summary>
    /// <param name = "_metVendorChangeRequest">MetVendorChangeRequest</param>
    /// <param name = "_subRangeValue">METSubrangeId</param>
    public void processItemSubRangeChilds(MetVendorChangeRequest _metVendorChangeRequest, METSubrangeId   _subRangeValue)
    {
        METInventItemOrderSetup metInventItemOrderSetup;
        MetVendorChangeRequest  MetVendorChangeRequestItemSub;

        while select metInventItemOrderSetup
            where metInventItemOrderSetup.ItemId != _metVendorChangeRequest.ItemId
                && metInventItemOrderSetup.SiteId == _metVendorChangeRequest.SiteId
                && metInventItemOrderSetup.SubrangeId == _subRangeValue
        {
            this.validateVendorChangeRequestsInterComp(metInventItemOrderSetup.ItemId, metInventItemOrderSetup.SiteId);
        }

    }

    /// <summary>
    /// This method is to validate the change request agaist item and Site.
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_siteId">InventSiteId</param>
    /// <returns></returns>
    public boolean validateVendorChangeRequestsInterComp(ItemId _itemId, InventSiteId _siteId)
    {
        boolean                 ret = true;
        METVendorChangeRequest  vendorChangeRequest;
        ReqItemTable            reqItemTable;
        InventDim               inventDim;

        select firstonly vendorChangeRequest
            where vendorChangeRequest.ItemId == _itemId
                && vendorChangeRequest.SiteId == _siteId
                && vendorChangeRequest.Status != METVendChangeReqStatus::Completed
                && vendorChangeRequest.ChangeReqEffectiveDate <= currentDate;

        select firstonly reqItemTable
            exists join inventDim
                where inventDim.inventDimId == reqItemTable.CovInventDimId
                && reqItemTable.ItemId == _itemId
                && inventDim.InventLocationId == vendorChangeRequest.InventLocationId
                && inventDim.InventSiteId == _siteId;
        
        if (reqItemTable.RecId && reqItemTable.ReqPOType == ReqPOType::Purch && reqItemTable.METInterCompanySourced == NoYes::Yes)
        {
            ReqItemTable    reqItemTableInterComp;
            InventDim       invDimInterComp;

            select firstOnly reqItemTableInterComp
                where reqItemTableInterComp.ItemId == vendorChangeRequest.ItemId
                join RecId from invDimInterComp
                where invDimInterComp.InventDimId == reqItemTableInterComp.CovInventDimId
                && invDimInterComp.InventSiteId == vendorChangeRequest.SiteId
                && invDimInterComp.InventLocationId == vendorChangeRequest.InventLocationId
                && reqItemTableInterComp.ReqPOType == ReqPOType::Purch
                && reqItemTableInterComp.METInterCompanySourced == NoYes::Yes;

            if (reqItemTableInterComp.RecId)
            {
                if (this.validateInterCompanyVendorChangeRequest(inventParameters.METInterCompanyPurchaseLegalEntity, vendorChangeRequest.ItemId, vendorChangeRequest.SiteId, vendorChangeRequest.InventLocationId))
                {
                    this.processVendChangeReqInterCompData(vendorChangeRequest, reqItemTable);
                }
            }

            if (!reqItemTableInterComp.RecId && !vendorChangerequestsProcessed.in(vendorChangeRequest.RecId))
            {
                vendorChangeRequest.selectForUpdate(true);
                vendorChangeRequest.Status = METVendChangeReqStatus::Error;
                vendorChangeRequest.ChangeRequestLog += "@MET:NoItemCoverageError";
                vendorChangeRequest.update();
                vendorChangerequestsProcessed.add(vendorChangeRequest.RecId);
                ret = false;
            }
        }
        return ret;
    }

    /// <summary>
    /// Updates the vendor change request status to waiting for the greater than today records.
    /// </summary>
    /// <param name = "_metVendorChangeRequest">Vendor change request record.</param>
    private void updateWaitingStatusForRecords(MetVendorChangeRequest _metVendorChangeRequest)
    {
        currentDate = DateTimeUtil::date(DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::utcNow(), DateTimeUtil::getUserPreferredTimeZone()));

        MetVendorChangeRequest metVendorChangeRequest;

        update_recordset metVendorChangeRequest
            setting Status = METVendChangeReqStatus::Waiting
            where metVendorChangeRequest.ChangeReqEffectiveDate > currentDate
            && metVendorChangeRequest.SiteId == _metVendorChangeRequest.SiteId;
    }

    /// <summary>
    /// This is where all successfully completed records are processed.
    /// </summary>
    /// <param name = "_metVendorChangeRequest">Vendor change request record</param>
    /// <param name = "_reqItemTable">Item coverage record</param>
    /// <param name = "_itemId">Item number</param>
    /// <param name = "_cascadeCSubordinateSite">Check to cascade change to Campbhells subordinate sites.</param>
    private void processNoErrorRecords(MetVendorChangeRequest _metVendorChangeRequest, ReqItemTable _reqItemTable, ItemId _itemId = '', boolean _cascadeCSubordinateSite = false)
    {
        ItemId itemId;
        METSIteControllingAndSubOrdinateSetup cControllingSiteSetup;

        //CB915_CampbellsSupplierChangeProcess - start
        cControllingSiteSetup = METSIteControllingAndSubOrdinateSetup::findBySite(_metVendorChangeRequest.SiteId);

        if (cControllingSiteSetup.RecId)
        {
            if (cControllingSiteSetup.IsControllingSite == NoYes::No && _cascadeCSubordinateSite == false)
            {
                vendorChangerequestsProcessed.add(_metVendorChangeRequest.RecId);
                return;
            }
        }
        //CB915_CampbellsSupplierChangeProcess - end

        if (!_itemId)
        {
            itemId = _metVendorChangeRequest.ItemId;
        }

        // Update the item coverage vendor with the pending vendor number.
        VendAccount vendAccount = _reqItemTable.VendId;
        VendAccount pendingVendAccount = METReqItemTable::find(_reqItemTable.RecId).PendingVendAccountNumber;

        //Modified the below condition to fix the Bug 280999 -CB886 - Supplier Change not processed for Child Codes
        if (_reqItemTable.RecId && pendingVendAccount)
        {
            ttsbegin;
            _reqItemTable.reread();
            _reqItemTable.selectForUpdate(true);
            _reqItemTable.VendId = pendingVendAccount;
            _reqItemTable.update();
            ttscommit;
        }

        //Task110346_CB409-D365ToPIM-Supplier change request- add Pending vendor account - start
        if (vendAccountNumber != pendingVendAccount)
        {
            vendAccountNumber = pendingVendAccount;
            vendAccountNumberList.addEnd(vendAccountNumber);
        }

        //set item number
        if (itemNumber != _reqItemTable.ItemId)
        {
            itemNumber = _reqItemTable.ItemId;
        }

        //add inventlocation
        coverageWareHouseIdList.addEnd(_metVendorChangeRequest.InventLocationId);
        //Task110346_CB409-D365ToPIM-Supplier change request- end

        // Clear the pending vendor number and date when there is no error.
        this.clearPendingVendorAccountFields(_reqItemTable.RecId);

        // Pricelist of vendor to close
        GUPVendPriceAdmTable gupVendPriceAdmTable;
        GUPVendPriceAdmTrans gupVendPriceAdmTrans;

        update_recordset gupVendPriceAdmTrans
        setting ToDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())
        exists join gupVendPriceAdmTable
            where gupVendPriceAdmTable.JournalNum == gupVendPriceAdmTrans.JournalNum
            && gupVendPriceAdmTable.InventSiteId == _metVendorChangeRequest.SiteId
            && gupVendPriceAdmTable.AccountRelation == vendAccount
            && (!calledFromPackChange
                || (calledFromPackChange 
                    && gupVendPriceAdmTrans.ToDate == Global::dateNull()
                    && gupVendPriceAdmTrans.ItemNum == itemNumber));

        // Vendor Price term agreements to close.
        GUPPriceTermJournalTable gupPriceTermJournalTable;
        GUPPriceTermJournalTrans gupPriceTermJournalTrans;
        GUPPricingRuleConditionView gupPricingRuleConditionView;

        if (!calledFromPackChange)
        {
            while select forupdate gupPriceTermJournalTrans
                exists join gupPriceTermJournalTable
                    where gupPriceTermJournalTable.AgreementId == gupPriceTermJournalTrans.AgreementId
                      && gupPriceTermJournalTable.InventSiteId == _metVendorChangeRequest.SiteId
                      && gupPriceTermJournalTable.AccountRelation == vendAccount
            {
                gupPriceTermJournalTrans.ValidTo = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
                gupPriceTermJournalTrans.update();
            }
        }
        else
        {
            while select forupdate gupPriceTermJournalTrans
                exists join gupPriceTermJournalTable
                    where gupPriceTermJournalTable.AgreementId == gupPriceTermJournalTrans.AgreementId
                      && gupPriceTermJournalTable.InventSiteId == _metVendorChangeRequest.SiteId
                      && gupPriceTermJournalTable.AccountRelation == vendAccount
                      && gupPriceTermJournalTrans.ValidTo == Global::dateNull()
                exists join gupPricingRuleConditionView
                    where gupPricingRuleConditionView.PricingRule == gupPriceTermJournalTrans.PricingRule
                      && (gupPricingRuleConditionView.Attribute1 == itemNumber
                          || gupPricingRuleConditionView.Attribute2 == itemNumber)
            {
                gupPriceTermJournalTrans.ValidTo = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
                gupPriceTermJournalTrans.update();
            }
        }

        //CB915_CampbellsSupplierChangeProcess - start
        if (cControllingSiteSetup.RecId && cControllingSiteSetup.IsControllingSite)
        {
            METVendorChangeRequest subordinateVendorRequest;
            METSIteControllingAndSubOrdinateSetup subordinateSetup;

            this.updateVendorChangeRequestStatus(_metVendorChangeRequest);

            while select subordinateVendorRequest
                where subordinateVendorRequest.ItemId == itemNumber
                exists join subordinateSetup
                    where subordinateSetup.SiteId == subordinateVendorRequest.SiteId
                    &&    subordinateSetup.IsControllingSite == NoYes::No
                    &&    subordinateSetup.ControllingSiteId == cControllingSiteSetup.SiteId
            {
                ReqItemTable reqItemTableCSite;
                InventDim inventDimCSite;

                select firstonly reqItemTableCSite
                    exists join inventDimCSite
                        where inventDimCSite.inventDimId == reqItemTableCSite.CovInventDimId
                        && reqItemTableCSite.ItemId == subordinateVendorRequest.ItemId
                        && inventDimCSite.InventLocationId == subordinateVendorRequest.InventLocationId
                        && inventDimCSite.InventSiteId == subordinateVendorRequest.SiteId;

                if (vendorChangerequestsProcessed.in(subordinateVendorRequest.RecId))
                {
                    vendorChangerequestsProcessed.remove(subordinateVendorRequest.RecId);
                }

                if (this.validateVendorChangeRequest(subordinateVendorRequest, reqItemTableCSite))
                {
                    this.processNoErrorRecords(subordinateVendorRequest, reqItemTableCSite, itemNumber, true);
                    this.updateVendorChangeRequestStatus(subordinateVendorRequest);
                }
            }
            //CB915_CampbellsSupplierChangeProcess - end
        }
    }

    /// <summary>
    /// This is where all successfully completed records are processed.
    /// </summary>
    /// <param name = "_metVendorChangeRequest">Vendor change request record</param>
    /// <param name = "_reqItemTable">Item coverage record</param>
    /// <param name = "_itemId">Item number</param>
    public void processVendChangeReqInterCompData(MetVendorChangeRequest _metVendorChangeRequest, ReqItemTable _reqItemTable, ItemId _itemId = '')
    {
        ItemId itemId;

        if (!_itemId)
        {
            itemId = _metVendorChangeRequest.ItemId;
        }

        // Update the item coverage vendor with the pending vendor number.
        VendAccount vendAccount = _reqItemTable.VendId;
        VendAccount pendingVendAccount = METReqItemTable::find(_reqItemTable.RecId).PendingVendAccountNumber;

        if (_reqItemTable.RecId)
        {
            _reqItemTable.selectForUpdate(true);
            _reqItemTable.VendId = pendingVendAccount;
            _reqItemTable.update();
        }

        if (vendAccountNumber != pendingVendAccount)
        {
            vendAccountNumber = pendingVendAccount;
            vendAccountNumberList.addEnd(vendAccountNumber);
        }

        //set item number
        if (itemNumber != _reqItemTable.ItemId)
        {
            itemNumber = _reqItemTable.ItemId;
        }

        // Clear the pending vendor number and date when there is no error.
        this.clearPendingVendorAccountFields(_reqItemTable.RecId);

        // Pricelist of vendor to close
        GUPVendPriceAdmTable gupVendPriceAdmTable;
        GUPVendPriceAdmTrans gupVendPriceAdmTrans;

        update_recordset gupVendPriceAdmTrans
        setting ToDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())
        exists join gupVendPriceAdmTable
            where gupVendPriceAdmTable.JournalNum == gupVendPriceAdmTrans.JournalNum
            && gupVendPriceAdmTable.InventSiteId == _metVendorChangeRequest.SiteId
            && gupVendPriceAdmTable.AccountRelation == vendAccount
            && (!calledFromPackChange
                || (calledFromPackChange 
                    && gupVendPriceAdmTrans.ToDate == Global::dateNull()
                    && gupVendPriceAdmTrans.ItemNum == itemNumber));

        // Vendor Price term agreements to close.
        GUPPriceTermJournalTable gupPriceTermJournalTable;
        GUPPriceTermJournalTrans gupPriceTermJournalTrans;
        GUPPricingRuleConditionView gupPricingRuleConditionView;

        if (!calledFromPackChange)
        {
            while select forupdate gupPriceTermJournalTrans
                exists join gupPriceTermJournalTable
                    where gupPriceTermJournalTable.AgreementId == gupPriceTermJournalTrans.AgreementId
                      && gupPriceTermJournalTable.InventSiteId == _metVendorChangeRequest.SiteId
                      && gupPriceTermJournalTable.AccountRelation == vendAccount
            {
                gupPriceTermJournalTrans.ValidTo = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
                gupPriceTermJournalTrans.update();
            }
        }
        else
        {
            while select forupdate gupPriceTermJournalTrans
                exists join gupPriceTermJournalTable
                    where gupPriceTermJournalTable.AgreementId == gupPriceTermJournalTrans.AgreementId
                      && gupPriceTermJournalTable.InventSiteId == _metVendorChangeRequest.SiteId
                      && gupPriceTermJournalTable.AccountRelation == vendAccount
                      && gupPriceTermJournalTrans.ValidTo == Global::dateNull()
                exists join gupPricingRuleConditionView
                    where gupPricingRuleConditionView.PricingRule == gupPriceTermJournalTrans.PricingRule
                      && (gupPricingRuleConditionView.Attribute1 == itemNumber
                          || gupPricingRuleConditionView.Attribute2 == itemNumber)
            {
                gupPriceTermJournalTrans.ValidTo = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
                gupPriceTermJournalTrans.update();
            }
        }
        this.updateVendorChangeRequestStatus(_metVendorChangeRequest);
    }

    /// <summary>
    /// Validated the vendor change request and update change request log.
    /// </summary>
    /// <param name = "_metVendorChangeRequest">Vendor change request record</param>
    /// <param name = "_reqItemTable">Item coverage record</param>
    /// <returns>A boolean value based on success true, Otherwise false</returns>
    private boolean validateVendorChangeRequest(METVendorChangeRequest _metVendorChangeRequest, ReqItemTable _reqItemTable)
    {
        boolean ret = true;
        PurchLine purchLine;
        InventDim inventDimLoc;
        METChangeRequestLog errorLog;
        METVendorChangeRequest vendorChangeReq;
        
        METInventItemOrderSetup metInventItemOrderSetup = METInventItemOrderSetup::findByItemAndSite(_metVendorChangeRequest.ItemId, _metVendorChangeRequest.SiteId);
        ItemId subRangeItem = metInventItemOrderSetup.SubrangeId;
        METTempItemPackChg tempItemPackChange = metInventItemOrderSetup.TempItemPackChg;
        //CB915_CampbellsSupplierChangeProcess - start
        METSiteControllingAndSubOrdinateSetup cSiteSetup = METSiteControllingAndSubOrdinateSetup::findBySite(_metVendorChangeRequest.SiteId);
        //CB915_CampbellsSupplierChangeProcess - end

        //CB915_CampbellsSupplierChangeProcess - start
        if (!cSiteSetup.RecId)
        //CB915_CampbellsSupplierChangeProcess - end
        {
            if (subRangeItem)
            {
                select firstonly RecId from purchLine
                exists join inventDimLoc
                    where inventDimLoc.InventDimId == purchLine.InventDimId
                exists join metInventItemOrderSetup
                    where metInventItemOrderSetup.ItemId == purchLine.ItemId
                exists join vendorChangeReq
                    where vendorChangeReq.ItemId == metInventItemOrderSetup.ItemId
                    && vendorChangeReq.SiteId == metInventItemOrderSetup.SiteId
                    && purchLine.PurchStatus == PurchStatus::Backorder
                    && inventDimLoc.InventLocationId == _metVendorChangeRequest.InventLocationId
                    && inventDimLoc.InventSiteId == _metVendorChangeRequest.SiteId
                    && metInventItemOrderSetup.SubRangeId == subRangeItem;
            }
            else
            {
                select firstonly RecId from purchLine
                exists join inventDimLoc
                    where inventDimLoc.inventDimId == purchLine.InventDimId
                    && purchLine.PurchStatus == PurchStatus::Backorder
                    && purchLine.ItemId == _metVendorChangeRequest.ItemId
                    && inventDimLoc.InventLocationId == _metVendorChangeRequest.InventLocationId
                    && inventDimLoc.InventSiteId == _metVendorChangeRequest.SiteId;
            }
       
            if (purchLine.RecId)
            {
                if (subRangeItem)
                {
                    errorLog = strFmt("@MET:ErrorOpenPOSubRange", subRangeItem);
                }
                else
                {
                    errorLog = strFmt("@MET:ErrorOpenPO", _metVendorChangeRequest.ItemId);
                }

                ret = false;
            }
        }

        METReqItemTable metReqItemTable = METReqItemTable::find(_reqItemTable.RecId);

        if (!metReqItemTable.PendingVendAccountNumber || !metReqItemTable.PendingVendChangeDate)
        {
            errorLog += "@MET:ErrorPendingVendorMiss";
            ret = false;
        }

        if (tempItemPackChange)
        {
            errorLog += strFmt("@MET:ErrorPendingPackChanges", _metVendorChangeRequest.ItemId);
            ret = false;
        }

        //CB915_CampbellsSupplierChangeProcess - start
        if (cSiteSetup.RecId)
        {
            METSiteControllingAndSubOrdinateSetup cControllingSite;
            ReqItemTable                          reqItemTableCSite;
            METReqItemTable                       metReqItemTableCSite;
            InventDim                             inventDimCSite;

            cControllingSite = (!cSiteSetup.IsControllingSite) ? cSiteSetup.controllingSiteSetup() : cSiteSetup;

            select firstonly RecId from reqItemTableCSite
                join InventLocationId, InventSiteId from inventDimCSite
                    where inventDimCSite.inventDimId == reqItemTableCSite.CovInventDimId
                        && reqItemTableCSite.ItemId == _metVendorChangeRequest.ItemId
                        && inventDimCSite.InventSiteId == cControllingSite.SiteId
                join PendingVendAccountNumber from metReqItemTableCSite
                        where metReqItemTableCSite.RefRecId == reqItemTableCSite.RecId;
                
            if (!metReqItemTableCSite.PendingVendAccountNumber)
            {
                MetVendorChangeRequest metVendorChangeRequesCSite;

                select firstonly RecId from metVendorChangeRequesCSite
                    where metVendorChangeRequesCSite.Status != METVendChangeReqStatus::Completed
                        && metVendorChangeRequesCSite.InventLocationId == inventDimCSite.InventLocationId
                        && metVendorChangeRequesCSite.SiteId == inventDimCSite.InventSiteId
                        && metVendorChangeRequesCSite.ItemId == _metVendorChangeRequest.ItemId;

                if (metVendorChangeRequesCSite.RecId)
                {
                    errorLog += strFmt("@MET:SupplierChangeSubordinateSiteError");
                    ret = false;
                }
            }
        }
        //CB915_CampbellsSupplierChangeProcess - end

        if (ret && !vendorChangerequestsProcessed.in(_metVendorChangeRequest.RecId))
        {
            _metVendorChangeRequest.selectForUpdate(true);
            _metVendorChangeRequest.Status = METVendChangeReqStatus::Waiting;
            _metVendorChangeRequest.ChangeRequestLog = '';
            _metVendorChangeRequest.update();
        }
        else
        {
            if (!vendorChangerequestsProcessed.in(_metVendorChangeRequest.RecId))
            {
                _metVendorChangeRequest.selectForUpdate(true);
                _metVendorChangeRequest.Status = METVendChangeReqStatus::Error;
                _metVendorChangeRequest.ChangeRequestLog = errorLog;
                _metVendorChangeRequest.update();
                vendorChangerequestsProcessed.add(_metVendorChangeRequest.RecId);
            }
        }

        return ret;
    }

/// <summary>
/// Get subrange value for vendor change request process.
/// </summary>
/// <param name = "_itemId">Item ID</param>
/// <param name = "_siteId">Site ID</param>
/// <returns>A Subrange value</returns>
private METSubrangeId getSubRangeValue(ItemId _itemId, InventSiteId _siteId)
{
    METInventItemOrderSetup metInventItemOrderSetup = METInventItemOrderSetup::findByItemAndSite(_itemId, _siteId);
    METSubrangeId           subRangeValue           = metInventItemOrderSetup.SubrangeId;
    
    return subRangeValue;
}

    /// <summary>
    /// Update the vendor change request status and change request log based on the PO, if not TO record which processed recently.
    /// </summary>
    /// <param name = "_metVendorChangeRequest">_metVendorChangeRequest is a child vendor change request when there is no PO.</param>
    /// <param name = "_metVendorChangeRequestPO">_metVendorChangeRequestPO is a parent vendor change request.</param>
    private void updateVendorChangeRequestStatus(MetVendorChangeRequest _metVendorChangeRequest, MetVendorChangeRequest _metVendorChangeRequestPO = null)
    {
        if (!vendorChangerequestsProcessed.in(_metVendorChangeRequest.RecId))
        {
            _metVendorChangeRequest.selectForUpdate(true);

            if (_metVendorChangeRequestPO.RecId)
            {
                _metVendorChangeRequest.Status = _metVendorChangeRequestPO.Status;
                _metVendorChangeRequest.ChangeRequestLog = _metVendorChangeRequestPO.ChangeRequestLog;
            }
            else
            {
                _metVendorChangeRequest.Status = METVendChangeReqStatus::Completed;
                _metVendorChangeRequest.ChangeRequestLog = strFmt("@MET:VendorUpdateSuccess", DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::utcNow(), DateTimeUtil::getUserPreferredTimeZone()));
            }
        
            _metVendorChangeRequest.selectForUpdate(true);
            _metVendorChangeRequest.update();
            vendorChangerequestsProcessed.add(_metVendorChangeRequest.RecId);
        }
    }

    /// <summary>
    /// Clears the pending vendor account fields.
    /// </summary>
    /// <param name = "_refRecid">Item coverage record id</param>
    private void clearPendingVendorAccountFields(RefRecId _refRecid)
    {
        // Clear the pending vendor number and date.
        METReqItemTable metReqItemTable = METReqItemTable::find(_refRecid, true);

        if (metReqItemTable.RecId)
        {
            metReqItemTable.PendingVendAccountNumber = '';
            metReqItemTable.PendingVendChangeDate = utcdatetimenull();
            metReqItemTable.update();
        }
    }

    /// <summary>
    /// Process the transfer order records related to purchase order.
    /// </summary>
    /// <param name = "_metVendorChangeRequest">_metVendorChangeRequest</param>
    private void updateTransferOrderRelatedToPO(METVendorChangeRequest _metVendorChangeRequest)
    {
        ReqItemTable reqItemTableTransfer;
        InventDim inventDim;
        MetVendorChangeRequest metVendorChangeRequestTransfer;

        while select reqItemTableTransfer
            join RecId from inventDim
                where inventDim.inventDimId == reqItemTableTransfer.CovInventDimId
                && reqItemTableTransfer.ItemId == _metVendorChangeRequest.ItemId
                && reqItemTableTransfer.InventLocationIdReqMain == _metVendorChangeRequest.InventLocationId
                && reqItemTableTransfer.ReqPOType == ReqPOType::Transfer
            join metVendorChangeRequestTransfer
                where metVendorChangeRequestTransfer.SiteId == inventDim.InventSiteId
                && metVendorChangeRequestTransfer.ItemId == _metVendorChangeRequest.ItemId
                && metVendorChangeRequestTransfer.InventLocationId == inventDim.InventLocationId
                && metVendorChangeRequestTransfer.Status != METVendChangeReqStatus::Completed
        {
            if (_metVendorChangeRequest.Status != METVendChangeReqStatus::Error 
               && this.validateVendorChangeRequest(metVendorChangeRequestTransfer, reqItemTableTransfer))
            {
                this.processNoErrorRecords(metVendorChangeRequestTransfer, reqItemTableTransfer);
            }

            this.updateVendorChangeRequestStatus(metVendorChangeRequestTransfer, _metVendorChangeRequest);
            this.updateRelatedChilds(metVendorChangeRequestTransfer);
        }
    }

    /// <summary>
    /// updates the vendor change requests for all the child items based on parent item.
    /// </summary>
    /// <param name = "_metVendorChangeRequest">_metVendorChangeRequest</param>
    private void updateChangeReqForParentChildItem(METVendorChangeRequest _metVendorChangeRequest)
    {
        METSalesItemSubstitutionParentChild parent;
        ReqItemTable childReqItem;
        InventDim childInventDim;
        METVendorChangeRequest childVendChangeReq;

        //Modified the below while loop to fix the Bug 280999 - CB886 - Supplier Change not processed for Child Codes
        while select ChildItemID from parent
                    where parent.ParentItemID == _metVendorChangeRequest.ItemId
                join childReqItem
                    where childReqItem.ItemId == parent.ChildItemID
                join childInventDim
                    where childInventDim.inventDimId == childReqItem.CovInventDimId
                        && childInventDim.InventSiteId == _metVendorChangeRequest.SiteId
                        && childInventDim.InventLocationId == _metVendorChangeRequest.InventLocationId
        {
            if (_metVendorChangeRequest.Status != METVendChangeReqStatus::Error)
            {
                //Modified the below condition to fix the Bug 280999 - CB886 - Supplier Change not processed for Child Codes
                this.processNoErrorRecords(_metVendorChangeRequest, childReqItem, childReqItem.ItemId);
            }
        }
    }

    /// <summary>
    /// Inter company PO updates the vendor change requests for all the child items based on parent item.
    /// </summary>
    /// <param name = "_metVendorChangeRequest">_metVendorChangeRequest</param>
    private void updateChangeReqForParentChildItemInterCompPO(METVendorChangeRequest _metVendorChangeRequest)
    {
        METSalesItemSubstitutionParentChild parent;

        while select parent
            where parent.ParentItemID == _metVendorChangeRequest.ItemId
                && parent.InventSiteId == _metVendorChangeRequest.SiteId
        {
            this.validateVendorChangeRequestsInterComp(parent.ChildItemID, parent.InventSiteId);
        }
    }

    /// <summary>
    /// Updates the vendor change requests for all the child items(temporary pack change) based on parent item.
    /// </summary>
    /// <param name = "_metVendorChangeRequest">Input the vendor change request record.</param>
    private void updateTemporaryItemPackChangeRecords(MetVendorChangeRequest _metVendorChangeRequest)
    {
        METInventItemOrderSetup metInventItemOrderSetup = METInventItemOrderSetup::findByItemAndSite(_metVendorChangeRequest.ItemId, _metVendorChangeRequest.SiteId);

        if (metInventItemOrderSetup.TempItemPackChg)
        {
            METVendorChangeRequest tempVendChangeReq;

            select firstonly forupdate tempVendChangeReq
                where tempVendChangeReq.SiteId == _metVendorChangeRequest.SiteId
                 && tempVendChangeReq.ItemId == metInventItemOrderSetup.TempItemPackChg;

            if (tempVendChangeReq.RecId && !vendorChangerequestsProcessed.in(tempVendChangeReq.RecId))
            {
                tempVendChangeReq.Status = _metVendorChangeRequest.Status;
                tempVendChangeReq.ChangeRequestLog = _metVendorChangeRequest.ChangeRequestLog;
                tempVendChangeReq.update();
                vendorChangerequestsProcessed.add(tempVendChangeReq.RecId);

                this.updateRelatedChilds(tempVendChangeReq);
            }
        }

    }

/// <summary>
/// Update all the linked child records (Substitue,Temporary pack change, Transfer order).
/// </summary>
/// <param name = "_metVendorChangeRequest">_metVendorChangeRequest</param>
private void updateRelatedChilds(MetVendorChangeRequest _metVendorChangeRequest)
{
    this.updateTemporaryItemPackChangeRecords(_metVendorChangeRequest);
    this.updateChangeReqForParentChildItem(_metVendorChangeRequest);
    this.updateTransferOrderRelatedToPO(_metVendorChangeRequest);
}

/// <summary>
/// Inter company PO Update all the linked child records
/// </summary>
/// <param name = "_metVendorChangeRequest">_metVendorChangeRequest</param>
private void updateRelatedChildsInterCompPO(MetVendorChangeRequest _metVendorChangeRequest)
{
    this.updateChangeReqForParentChildItemInterCompPO(_metVendorChangeRequest);
}

    /// <summary>
    /// Update
    /// </summary>
    /// <param name = "_reqItemTable">_reqItemTable</param>
    /// <param name = "_metVendorChangeRequest">_metVendorChangeRequest</param>
    /// <returns>boolean value.</returns>
    private boolean updateItemSubrangeAndPOTORecords(ReqItemTable _reqItemTable, METVendorChangeRequest _metVendorChangeRequest)
    {
        boolean ret;
        
        ret = this.validateVendorChangeRequest(_metVendorChangeRequest, _reqItemTable);
        
        if (ret)
        {
            this.processNoErrorRecords(_metVendorChangeRequest, _reqItemTable);
            this.updateVendorChangeRequestStatus(_metVendorChangeRequest);
        }

        this.updateRelatedChilds(_metVendorChangeRequest);

        return ret;
    }

///Task110346_CB409-D365ToPIM-Supplier change request business event for completion status
/// <summary>
/// Trigger business event once the supplier change status is complete without errors
/// </summary>
/// <param name = "_itemId">ItemId from the vendor change request </param>
/// <param name = "_vendAccount">Pending vendor account</param>
/// <param name = "_coverageWareHouseIdList">Item coverage parent and child warehouses for supplier change</param>
private void triggerSupplierChangeCompleteBusinessEvent(ItemId _itemId, List _coverageWhsIdVendAccountNumberList)
{
    if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METSupplierChangeCompletedBusinessEvent)))
    {
        METSupplierChangeCompletedBusinessEvent::newFromSupplierChangeCompleted(_itemId, _coverageWhsIdVendAccountNumberList).send();
    }
}

    /// <summary>
    /// Gets the Parent vendor change request data.
    /// </summary>
    /// <param name = "_childRequest">Send the child vendor change request as a input.</param>
    /// <returns>Returns the parent vendor change request</returns>
    private METVendorChangeRequest getParentvendorChangeRequest(METVendorChangeRequest _childRequest)
    {
        METVendorChangeRequest parentVendorChangeRequest;
        METInventItemOrderSetup metInventItemOrderSetup;

        select firstonly parentVendorChangeRequest
            exists join metInventItemOrderSetup
            where parentVendorChangeRequest.SiteId == metInventItemOrderSetup.SiteId
            && parentVendorChangeRequest.ItemId == metInventItemOrderSetup.ItemId
            && metInventItemOrderSetup.TempItemPackChg == _childRequest.ItemId
            && metInventItemOrderSetup.SiteId == _childRequest.SiteId
            && parentVendorChangeRequest.Status != METVendChangeReqStatus::Completed;

        if (!parentVendorChangeRequest.RecId)
        {
            METSalesItemSubstitutionParentChild child;

            select firstonly parentVendorChangeRequest
                where parentVendorChangeRequest.SiteId == _childRequest.SiteId
                && parentVendorChangeRequest.InventLocationId == _childRequest.InventLocationId
                && parentVendorChangeRequest.Status != METVendChangeReqStatus::Completed
            join child
                where child.ParentItemID == parentVendorChangeRequest.ItemId
                && child.InventSiteId == parentVendorChangeRequest.SiteId
                && child.ChildItemID == _childRequest.ItemId;
        }

        return parentVendorChangeRequest;
    }

    /// <summary>
    /// Preparing the List of warehouse and vendor combinations for business event.
    /// </summary>
    /// <param name = "_warehouseId">Coverage Warehouse</param>
    /// <param name = "_vendorList">Pending Vendor account List from Item Coverage</param>
    private void addVendorCombinationsForWarehouse(str _warehouseId, List _vendorList)
    {
        ListIterator vendAccountNumberItr = new ListIterator(_vendorList);

        while (vendAccountNumberItr.more())
        {
            coverageWhsIdVendAccountNumberList.addEnd(strFmt("%1-%2", _warehouseId, vendAccountNumberItr.value()));
            vendAccountNumberItr.next();
        }
    }

    /// <summary>
    /// Runs the base price version job for the given vendor change request.
    /// </summary>
    /// <param name = "_vendorChangeRequest"></param>
    private void runBasePriceVersionJob(METVendorChangeRequest _vendorChangeRequest)
    {
        BatchHeader         header;
        SysRecurrenceData   sysRecurrenceData;
        Batch               batch;
        BatchJob            batchJob;
        BatchInfo           processBatchInfo;
        BatchRetries        noOfRetriesOnFailure = 4;
        GUPItemBasePriceCalcJob_All gupItemBasePriceCalcJob_All;
        GUPBasePriceVersion gupBasePriceVersion;
        #define.timeInSecondsDelay(2)
            
        // Setup the RunBaseBatch Job

        select firstonly AllowPurch, AllowSales, AllowInventoryCost, BlockActivation, VersionId
            from gupBasePriceVersion
            where gupBasePriceVersion.InventSiteId == _vendorChangeRequest.SiteId;
        if(!gupBasePriceVersion)
        {
            return;
        }

        InventDim           inventdim;

        inventdim.InventSiteId = _vendorChangeRequest.SiteId;
        inventdim = InventDim::findOrCreate(inventdim);

        Query               query = new Query(queryStr(GUPItemBasePriceCalc));
        query.dataSourceTable(tableNum(InventTable)).findRange(fieldNum(InventTable, ItemId)).value(queryValue(_vendorChangeRequest.ItemId));
        header = BatchHeader::construct();
        gupItemBasePriceCalcJob_All = GUPItemBasePriceCalcJob_All::construct();
        gupItemBasePriceCalcJob_All.parmItemId(_vendorChangeRequest.ItemId);
        gupItemBasePriceCalcJob_All.parmSiteId(_vendorChangeRequest.SiteId);
        gupItemBasePriceCalcJob_All.parmCalcDate(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
        gupItemBasePriceCalcJob_All.parmPurchPriceTransfer(gupBasePriceVersion.AllowPurch);
        gupItemBasePriceCalcJob_All.parmSalesPriceTransfer(gupBasePriceVersion.AllowSales);
        gupItemBasePriceCalcJob_All.parmCostPriceTransfer(gupBasePriceVersion.AllowInventoryCost);
        gupItemBasePriceCalcJob_All.parmBlockActivation(gupBasePriceVersion.BlockActivation);
        gupItemBasePriceCalcJob_All.parmBasePriceVersionId(gupBasePriceVersion.VersionId);
        gupItemBasePriceCalcJob_All.parmBasePriceActivatePrice(NoYes::Yes);
        gupItemBasePriceCalcJob_All.parmBasePriceDeltaCalculation(NoYes::Yes);
        gupItemBasePriceCalcJob_All.parmInventDimId(inventdim.inventDimId);
        gupItemBasePriceCalcJob_All.parmMETIncludeClaimFromVendor(NoYes::Yes);
        gupItemBasePriceCalcJob_All.setMETQuery(query);

        processBatchInfo = gupItemBasePriceCalcJob_All.batchInfo();
        
        processBatchInfo.parmRetriesOnFailure(noOfRetriesOnFailure);
        processBatchInfo.parmCaption("@MET:VendChgReqBase" + strFmt(" - %1, %2", _vendorChangeRequest.SiteId, _vendorChangeRequest.ItemId));

        if (InventParameters::find().METBasePriceJobRunAsUser)
        {
           header.parmExecutingBy(InventParameters::find().METBasePriceJobRunAsUser);
        }
        header.addTask(gupItemBasePriceCalcJob_All);

        // Set the recurrence data
        sysRecurrenceData = SysRecurrence::defaultRecurrence();
        sysRecurrenceData = SysRecurrence::setRecurrenceStartDateTime(sysRecurrenceData, DateTimeUtil::addSeconds(DateTimeUtil::utcNow(), #timeInSecondsDelay));
        sysRecurrenceData = SysRecurrence::setRecurrenceEndAfter(sysRecurrenceData, 1);
        header.parmRecurrenceData(sysRecurrenceData);
        // Set the batch alert configurations
        header.parmAlerts(NoYes::No, NoYes::Yes, NoYes::No, NoYes::Yes, NoYes::No);
        header.save();
    }
